CREATE OR REPLACE FUNCTION public.get_credit_wallet() RETURNS TABLE (user_id uuid, balance integer, lifetime_earned integer, lifetime_spent integer, vip_tier text, vip_until timestamp with time zone, last_ad_reward_at timestamp with time zone) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; INSERT INTO public.credit_wallets (user_id) VALUES (auth.uid()) ON CONFLICT (user_id) DO NOTHING; RETURN QUERY SELECT w.user_id, w.balance, w.lifetime_earned, w.lifetime_spent, w.vip_tier, w.vip_until, w.last_ad_reward_at FROM public.credit_wallets w WHERE w.user_id = auth.uid(); END; $$;